<?php $title='Clients';require __DIR__.'/../layouts/header.php';?><div class="pagehead"><div><h1>Manage Clients</h1><p>Search, review, update and archive client records.</p></div><a class="primary" href="<?=route('client.create')?>">+ Add Client</a></div><form class="toolbar" method="get" action="<?=route('clients')?>"><input name="q" value="<?=e($q??'')?>" placeholder="Search by client, email or phone"><button class="secondary">Search</button></form><div class="panel table-wrap"><table><thead><tr><th>Client</th><th>Type</th><th>Email</th><th>Phone</th><th>Balance</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($clients as $c):?><tr><td><strong><?=e($c['full_name'])?></strong><div class="muted"><?=e($c['client_no'])?></div></td><td><?=e($c['client_type'])?></td><td><?=e($c['email'])?></td><td><?=e($c['phone'])?></td><td><?=money((float)$c['live_balance'])?></td><td><span class="badge"><?=e($c['status'])?></span></td><td><a href="<?=route('client.view',['id'=>$c['id']])?>">Open</a></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../layouts/footer.php';?>
